import {slides,objectives,opticalState,scaleBar,clamp,opticsSource,imageReferences} from './microscope-science.js';
import {instrument} from './microscope-instrument.js';
import {createMicroRenderer} from './microscope-renderer.js';
export function createMicroscope(api){
 const root=document.querySelector('#microscope-app');let state={sample:'tomato',name:slides.tomato.name,objective:10,coarse:43,fine:0,light:68,iris:60,oil:false,panX:0,panY:0,approach:0,paused:false},active=false,renderer=null,drag=null,labels=false;
 const reduced=matchMedia('(prefers-reduced-motion: reduce)');
 const control=(id,label,min,max,value,step=1)=>`<label class="scope-slider" for="scope-${id}"><span>${label}<output id="scope-${id}-value">${value}</output></span><input id="scope-${id}" data-scope-input="${id}" type="range" min="${min}" max="${max}" step="${step}" value="${value}"></label>`;
 root.innerHTML=`<div class="scope-sample-bar"><div><span class="eyebrow">BỘ TIÊU BẢN / 05</span><span>Chọn một thế giới để nhìn gần hơn.</span></div><div class="scope-slides" role="group" aria-label="Chọn tiêu bản">${Object.entries(slides).map(([id,s],i)=>`<button data-slide="${id}" aria-pressed="${id==='tomato'}" style="--slide-color:${s.color}"><span class="slide-glass"><i></i><small>${String(i+1).padStart(2,'0')}</small></span><span>${s.name}<small>${s.latin}</small></span></button>`).join('')}</div></div>
 <div class="scope-workstation"><div class="scope-stage" id="scope-stage" role="region" aria-label="Bàn kính hiển vi. Cuộn chuột để tiến gần hoặc lùi khỏi thị kính." tabindex="0"><div class="scope-lab-background" aria-hidden="true"></div><div class="scope-bench" aria-hidden="true"></div><div class="scope-hud"><span><i></i> VNS / OPTICAL OBSERVATORY</span><span id="scope-mode">GÓC NHÌN THỨ NHẤT</span></div><div class="scope-instrument">${instrument}</div><div class="scope-hardware-label hardware-eyepiece">Thị kính 10×<span></span></div><div class="scope-hardware-label hardware-focus">Ốc lấy nét<span></span></div><div class="scope-hardware-label hardware-slide">Bàn tiêu bản<span></span></div><div class="scope-ocular" id="scope-ocular"><canvas id="scope-canvas" width="1000" height="1000" role="img" aria-label="Minh họa tế bào cà chua qua kính hiển vi"></canvas><div class="ocular-glass" aria-hidden="true"></div><div class="scope-reticle" aria-hidden="true"></div><div class="scope-scale"><span></span><small></small></div><div class="scope-lens-caption"><span id="scope-lens-name">CÀ CHUA</span><span id="scope-lens-mag">100×</span></div></div><div class="scope-entry"><span class="eyebrow">MỘT GÓC NHÌN. VẠN ĐIỀU MỚI.</span><p>Đặt mắt vào thị kính.</p><button class="button button-lime" data-scope="enter">Bắt đầu quan sát ${api.icon('arrow-right')}</button><span>Cuộn trong khung để tiến gần · Có thể dùng nút</span></div><button class="scope-exit" data-scope="exit">${api.icon('arrow-right')} Rời thị kính</button><div class="scope-observation-hint">Kéo vùng nhìn để dịch tiêu bản · Phím mũi tên để di chuyển</div><div class="scope-approach"><label for="scope-approach">Khoảng cách mắt</label><input id="scope-approach" data-scope-input="approach" type="range" min="0" max="100" value="0" aria-label="Tiến gần mắt vào thị kính"><span>Gần</span></div></div>
 <aside class="scope-console" aria-label="Điều khiển kính hiển vi"><div class="scope-console-heading"><span class="eyebrow">ĐIỀU CHỈNH QUANG HỌC</span><h2>Nhìn rõ hơn,<br>từng chút một.</h2></div><div class="scope-magnification"><span id="scope-total">100<small>×</small></span><p>Thị kính 10×<br>× vật kính <b id="scope-objective-label">10×</b></p></div><fieldset class="scope-objectives"><legend>Vật kính</legend><div>${objectives.map(n=>`<button data-objective="${n}" aria-pressed="${n===10}" class="objective-${n}">${n}×${n===100?'<small>Dầu</small>':''}</button>`).join('')}</div></fieldset><label class="scope-oil" hidden><input id="scope-oil" type="checkbox"> Dầu nhúng mô phỏng</label><div id="scope-focus-message" class="scope-focus-message" role="status">Chỉnh thô, rồi tinh chỉnh để tìm mặt phẳng nét.</div><div class="scope-focus-controls"><div class="scope-dial" aria-hidden="true"><span></span><i></i></div><div>${control('coarse','Chỉnh thô',0,100,43)}${control('fine','Chỉnh tinh',-5,5,0,.1)}</div></div><button class="scope-assist" data-scope="assist">${api.icon('search')} Hỗ trợ tìm nét</button><div class="scope-light-controls">${control('light','Độ sáng',0,100,68)}${control('iris','Khẩu độ mô phỏng',15,100,60)}</div><div class="scope-toggles"><button data-scope="pause" aria-pressed="false">${api.icon('pause')} Dừng mẫu sống</button><button data-scope="labels" aria-pressed="false">${api.icon('layers')} Gợi ý quan sát</button></div><div class="scope-pan"><span>Dịch tiêu bản</span><div><button data-pan="up" aria-label="Dịch tiêu bản lên">↑</button><button data-pan="left" aria-label="Dịch tiêu bản trái">←</button><button data-scope="center" aria-label="Đưa tiêu bản về tâm">◎</button><button data-pan="right" aria-label="Dịch tiêu bản phải">→</button><button data-pan="down" aria-label="Dịch tiêu bản xuống">↓</button></div></div><div class="scope-capture"><button data-scope="capture">${api.icon('download')} Chụp vùng nhìn</button><button data-scope="note">${api.icon('notebook')} Ghi vào sổ tay</button></div><p class="scope-console-note">Ảnh và thước là mô phỏng. Cấu trúc được giản lược theo ảnh tham khảo.</p></aside></div>
 <div class="scope-specimen-info"><div class="scope-description"><span class="eyebrow" id="scope-specimen-kind"></span><h2 id="scope-specimen-name"></h2><p id="scope-description"></p><div class="scope-feature-list" id="scope-features"></div></div><div class="scope-question"><span class="eyebrow">DỪNG LẠI VỚI MỘT CÂU HỎI</span><h3 id="scope-question"></h3><p id="scope-size"></p><p id="scope-limit"></p></div></div><details class="scope-references"><summary>Ảnh tham khảo & cách mô phỏng</summary><p>Minh họa được dựng bằng đồ họa lập trình dựa trên hình thái quan sát ở các nguồn dưới đây. Nút “Xem ảnh gốc” mở nguồn để bạn đối chiếu; ảnh có bản quyền không được chép vào thư viện. Các chế độ chụp ảnh ở nguồn (sáng trường, tương phản pha, phân cực) có thể tạo màu và độ tương phản khác nhau.</p><div>${Object.values(slides).map(s=>`<a href="${s.source.url}" target="_blank" rel="noopener"><span>${s.name}</span>${s.source.title} ↗</a>`).join('')}<a href="${opticsSource.url}" target="_blank" rel="noopener"><span>Vận hành</span>${opticsSource.title} ↗</a>${imageReferences.map(r=>`<a href="${r.url}" target="_blank" rel="noopener"><span>Đối chiếu ảnh</span>${r.title} ↗</a>`).join('')}</div><p>Quy ước: thị kính 10×, số trường giả định 18 mm, đường kính vùng nhìn = 18 mm / độ phóng đại vật kính. Cỡ tế bào và mật độ là giá trị minh họa; chuyển động mẫu sống làm chậm. Lấy nét, độ sáng, khẩu độ được mô phỏng định tính, không phải mô hình quang học đo lường đầy đủ.</p></details>`;
 const canvas=root.querySelector('#scope-canvas'),stage=root.querySelector('#scope-stage'),ocular=root.querySelector('#scope-ocular');renderer=createMicroRenderer(canvas,()=>state);
 function describe(){const s=slides[state.sample];state.name=s.name;root.querySelectorAll('[data-slide]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.slide===state.sample));root.querySelector('#scope-specimen-kind').textContent=s.kind;root.querySelector('#scope-specimen-name').innerHTML=`${s.name}<em>${s.latin}</em>`;root.querySelector('#scope-description').textContent=s.description;root.querySelector('#scope-features').innerHTML=s.features.map((f,i)=>`<span><i>${i+1}</i>${f}</span>`).join('');root.querySelector('#scope-question').textContent=s.question;root.querySelector('#scope-size').textContent=s.size;root.querySelector('#scope-limit').textContent=s.limit;root.querySelector('#scope-lens-name').textContent=s.name;canvas.setAttribute('aria-label',`Minh họa ${s.name}: ${s.features.join(', ')}`);root.querySelector('[data-scope="pause"]').disabled=!s.living;root.querySelector('#scope-features').classList.toggle('highlighted',labels)}
 function update(){const o=opticalState(state),s=slides[state.sample],bar=scaleBar(o.field);stage.style.setProperty('--approach',state.approach);stage.classList.toggle('is-looking',state.approach>.7);stage.classList.toggle('is-between',state.approach>.15&&state.approach<=.7);root.querySelector('.scope-entry').inert=state.approach>.15;stage.classList.toggle('is-reduced',reduced.matches);root.querySelector('#scope-total').innerHTML=`${o.total}<small>×</small>`;root.querySelector('#scope-lens-mag').textContent=o.total+'×';root.querySelector('#scope-objective-label').textContent=o.objective+'×';root.querySelectorAll('[data-objective]').forEach(b=>b.setAttribute('aria-pressed',Number(b.dataset.objective)===o.objective));root.querySelector('#scope-coarse').disabled=o.coarseLocked;root.querySelector('.scope-oil').hidden=o.objective!==100;root.querySelector('#scope-oil').checked=state.oil;const msg=o.sharpness>88?'Mặt phẳng nét đã rõ. Hãy quan sát cấu trúc.':o.coarseLocked?'Vật kính cao: dùng chỉnh tinh để lấy nét.':'Chỉnh thô, rồi chỉnh tinh để tìm mặt phẳng nét.';root.querySelector('#scope-focus-message').textContent=o.oilRequired?'Vật kính 100×: bật dầu nhúng mô phỏng để quan sát.':msg;root.querySelector('#scope-focus-message').classList.toggle('is-sharp',o.sharpness>88&&!o.oilRequired);canvas.style.filter=`blur(${o.oilRequired?Math.max(8,o.blur):o.blur}px) brightness(${o.brightness}) contrast(${o.contrast})`;root.querySelector('.scope-scale>span').style.width=bar.fraction*100+'%';root.querySelector('.scope-scale small').textContent=bar.value+' µm · mô phỏng';root.querySelector('.scope-dial').style.setProperty('--dial-angle',(state.coarse*3.6+state.fine*12)+'deg');for(const key of ['coarse','fine','light','iris']){root.querySelector('#scope-'+key).value=state[key];root.querySelector('#scope-'+key+'-value').textContent=state[key]+(['light','iris'].includes(key)?'%':'')}root.querySelector('#scope-approach').value=Math.round(state.approach*100);root.querySelector('#scope-mode').textContent=state.approach>.7?(s.living?'MẪU SỐNG · CHUYỂN ĐỘNG LÀM CHẬM':'TIÊU BẢN CỐ ĐỊNH'):'GÓC NHÌN THỨ NHẤT';root.querySelector('[data-scope="pause"]').setAttribute('aria-pressed',String(state.paused));root.querySelector('[data-scope="pause"]').innerHTML=api.icon(state.paused?'play':'pause')+(state.paused?' Tiếp tục mẫu sống':' Dừng mẫu sống');renderer.invalidate()}
 function approach(value){state.approach=clamp(value,0,1);update()}
 function pan(direction){const step=opticalState(state).field*.07;const delta={up:[0,-step],down:[0,step],left:[-step,0],right:[step,0]}[direction];if(!delta)return;state.panX=clamp(state.panX-delta[0],-1300,1300);state.panY=clamp(state.panY-delta[1],-1300,1300);update()}
 root.addEventListener('input',e=>{const key=e.target.dataset.scopeInput;if(!key)return;if(key==='approach'){approach(Number(e.target.value)/100);return}state[key]=Number(e.target.value);update()});
 root.querySelector('#scope-oil').addEventListener('change',e=>{state.oil=e.target.checked;update()});
 root.addEventListener('click',e=>{const slide=e.target.closest('[data-slide]');if(slide){state.sample=slide.dataset.slide;state.objective=10;state.coarse=43;state.fine=0;state.oil=false;state.panX=state.panY=0;state.paused=false;describe();update();return}const objective=e.target.closest('[data-objective]');if(objective){state.objective=Number(objective.dataset.objective);update();return}const move=e.target.closest('[data-pan]');if(move){pan(move.dataset.pan);return}const b=e.target.closest('[data-scope]');if(!b)return;switch(b.dataset.scope){case'enter':approach(1);stage.focus({preventScroll:true});break;case'exit':approach(0);break;case'assist':state.coarse=52;state.fine=state.objective===100?.9:state.objective===40?.5:0;update();break;case'pause':state.paused=!state.paused;update();break;case'labels':labels=!labels;b.setAttribute('aria-pressed',String(labels));root.querySelector('#scope-features').classList.toggle('highlighted',labels);if(labels)root.querySelector('.scope-specimen-info').scrollIntoView({behavior:reduced.matches?'instant':'smooth',block:'nearest'});break;case'center':state.panX=state.panY=0;update();break;case'capture':{const output=renderer.capture();output.toBlob(blob=>{if(!blob)return;const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`VNScape-${state.sample}-${state.objective*10}x.png`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)},'image/png');break}case'note':{const learner=api.getState();if(!learner.observedSlides.includes(state.sample))learner.observedSlides.push(state.sample);api.trackActivity?.();api.addNote(`Qua thị kính · ${state.name}`,`Tiêu bản: ${state.name} (${slides[state.sample].kind})\nThị kính 10× × vật kính ${state.objective}× = ${state.objective*10}×\nĐộ sáng: ${state.light}% · Chỉnh thô: ${state.coarse} · Chỉnh tinh: ${state.fine}\n\nMình quan sát thấy:\n\nCâu hỏi: ${slides[state.sample].question}\n\nLưu ý: đây là mô phỏng minh họa.\nNguồn đối chiếu: ${slides[state.sample].source.url}`);api.navigate('notebook');api.toast('Đã mở một trang sổ để ghi thêm quan sát.');break}}});
 stage.addEventListener('wheel',e=>{if(e.ctrlKey||e.target.closest('input,button'))return;const next=clamp(state.approach+clamp(e.deltaY,-120,120)/650,0,1);if(next===state.approach)return;e.preventDefault();approach(next)},{passive:false});
 ocular.addEventListener('pointerdown',e=>{if(state.approach<.7)return;drag={x:e.clientX,y:e.clientY,px:state.panX,py:state.panY};ocular.setPointerCapture(e.pointerId)});ocular.addEventListener('pointermove',e=>{if(!drag)return;const k=opticalState(state).field/ocular.clientWidth;state.panX=clamp(drag.px-(e.clientX-drag.x)*k,-1300,1300);state.panY=clamp(drag.py-(e.clientY-drag.y)*k,-1300,1300);update()});for(const event of ['pointerup','pointercancel','lostpointercapture'])ocular.addEventListener(event,()=>drag=null);
 stage.addEventListener('keydown',e=>{if(e.target.matches('input,button'))return;const map={ArrowUp:'up',ArrowDown:'down',ArrowLeft:'left',ArrowRight:'right'};if(map[e.key]){e.preventDefault();pan(map[e.key])}if(e.key==='Enter'){e.preventDefault();approach(state.approach>.7?0:1)}});
 document.addEventListener('visibilitychange',()=>{if(document.hidden)renderer.stop();else if(active)renderer.start()});reduced.addEventListener('change',update);describe();update();
 return {setActive(value){active=value;if(value&&!document.hidden)renderer.start();else renderer.stop()},getState:()=>({...state})};
}
